        public static Border Section(string title,string description,bool light){var stack=new StackPanel();stack.Children.Add(new TextBlock{Text=title,Foreground=Ink(light),FontSize=18,FontWeight=FontWeights.SemiBold});if(!string.IsNullOrWhiteSpace(description))stack.Children.Add(new TextBlock{Text=description,Foreground=Muted(light),TextWrapping=TextWrapping.Wrap,FontSize=12,Margin=new Thickness(0,7,0,14)});return new Border{CornerRadius=new CornerRadius(18),Background=Card(light),BorderBrush=Line(light),BorderThickness=new Thickness(1),Padding=new Thickness(20),Child=stack,Margin=new Thickness(0,0,0,16)};}
